import SwiftUI

struct CipollaInfoView: View {
    var body: some View {
        StudentDetailSheet(title: "Алгоритм Чиполлы", large: true) {
            MathExplainedText(text: "Находим все корни сравнения x² ≡ a по простому модулю p. Сначала приводим a по p. При a ≡ 0 корень нулевой, при p = 2 ответ равен a mod 2. Для нечётного простого p вычисляем символ Лежандра: значение −1 означает отсутствие корней.")
            MathExplainedText(text: "Затем перебираем δ = 0, 1, 2… до квадратичного невычета δ² − a. Если разность стала нулевой, ±δ уже дают ответ. В остальных случаях вводим квадратичное расширение поля с условием ω² = δ² − a. При ручном выборе δ проверяем те же условия.")
            StudentFormulaView(atoms: [.text("x₁,₂ ≡ ±"), .fractionPower("(δ + ω)", "p + 1", "2"), .text("(mod p)")])
            MathExplainedText(text: "Переводим показатель в двоичную систему, вычисляем последовательные квадраты, затем попарно перемножаем степени, соответствующие единицам. После каждого умножения заменяем ω² на δ² − a и приводим коэффициенты по p. Короткий отрицательный представитель допустим во всех произведениях. В конечной степени коэффициент при ω становится нулём. Полученное t и противоположный остаток p − t — корни; каждый проверяем подстановкой.")
